local config = {
  ui_story_32180401_1_1_dialog_content = "Okay, I'll cut to the chase then.",
  ui_story_32180401_1_2_dialog_content = "This job is from me personally. It's also a bit unconventional.",
  ui_story_32180401_1_3_dialog_content = "Whether it's an assignment from the Cloudrover Guild or you, Lady Sheol, I will treat it with the same respect.",
  ui_story_32180401_1_4_dialog_content = "You're so sweet, dear.",
  ui_story_32180401_1_5_dialog_content = "Actually, I got a bad debt on hand that I need you to handle.",
  ui_story_32180401_1_6_dialog_content = "Bad debt?",
  ui_story_32180401_1_7_dialog_content = "Yes.",
  ui_story_32180401_1_8_dialog_content = "Doesn't Cloudrover have specialists for that? Isa, for example? Although she's not working for the guild anymore.",
  ui_story_32180401_1_9_dialog_content = "But you do have more specialists than just her, right?",
  ui_story_32180401_1_10_dialog_content = "Correct. But, as I said, this debt is rather special, or more specifically, troublesome.",
  ui_story_32180401_1_11_dialog_content = "I'm afraid you're the only one who can help.",
  ui_story_32180401_1_12_dialog_content = "A debt that could bother you this much must be problematic...",
  ui_story_32180401_1_13_dialog_content = "(Is she being blackmailed by a particularly devious deadbeat? Well, this shouldn't be the case, given how shrewd Lady Sheol is...)",
  ui_story_32180401_1_14_dialog_content = "(But judging from her expressions, she does seem very troubled.)",
  ui_story_32180401_1_15_dialog_content = "I have a suggestion, Lady Sheol.",
  ui_story_32180401_1_16_dialog_content = "Please elaborate.",
  ui_story_32180401_1_17_dialog_content = "Let's un-retire Isa!",
  ui_story_32180401_1_18_dialog_content = "She's the most professional collector I've ever met! The effort will go a lot smoother with her help!",
  ui_story_32180401_1_19_dialog_content = "Unfortunately, from what I know of her, she won't be able to handle this particular case.",
  ui_story_32180401_1_20_dialog_content = "So I'll have to go alone...",
  ui_story_32180401_1_21_dialog_content = "Does that mean you'll take the job?",
  ui_story_32180401_1_22_dialog_content = "I don't think I have a choice. I'm sure from the moment I stepped inside the lounge, the only option was to accept the job.",
  ui_story_32180401_1_23_dialog_content = "Ah, only under such circumstances would you show your true cleverness.",
  ui_story_32180401_1_24_dialog_content = "However, about the bad debt, I don't hate it... Correction, I like it very much.",
  ui_story_32180401_1_25_dialog_content = "Mom...!",
  ui_story_32180401_1_26_dialog_content = "<size=45>Mom?!</size>",
  ui_story_32180401_1_27_dialog_content = "<size=30>Sigh, here comes the \"bad debt\"...</size>",
  ui_story_32180401_1_28_dialog_content = "You're back, Mom! It's so wonderful. I thought you abandoned me and would never come back!",
  ui_story_32180401_1_29_dialog_content = "Hey, who's this?",
  ui_story_32180401_1_30_dialog_content = "Oh, I know, this must be daddy! Dad!",
  ui_story_32180401_1_31_dialog_content = "Dad?!",
  ui_story_32180401_1_32_dialog_content = "Lady Sheol?!",
  ui_story_32180401_1_33_dialog_content = "I don't know you had a daughter?!",
  ui_story_32180401_1_34_dialog_content = "Don't panic, dear. This is not my daughter.",
  ui_story_32180401_1_35_dialog_content = "Or do I look the childrearing kind to you?",
  ui_story_32180401_1_36_dialog_content = "So who's this child?",
  ui_story_32180401_1_37_dialog_content = "This child is the \"bad debt\" I mentioned.",
  ui_story_32180401_1_38_dialog_content = "Huh?",
  ui_story_32180401_1_39_dialog_content = "That's only a metaphor. Please pick your jaw off the floor.",
  ui_story_32180401_1_40_dialog_content = "I do have an outstanding debt, but the deadbeat ran off and left the kid behind as payment.",
  ui_story_32180401_1_41_dialog_content = "So, why am I the only one who could do this job for you? Vice would be a better choice to look after the kid.",
  ui_story_32180401_1_42_dialog_content = "Actually, I'm asking you to take the child back home.",
  ui_story_32180401_1_43_dialog_content = "Me...?",
  ui_story_32180401_1_44_dialog_content = "Correct. They caught the deadbeat. He's currently \"atoning\" somewhere under Cloudrover's supervision.",
  ui_story_32180401_1_45_dialog_content = "I instructed my men to \"grill\" him a little, trying to find out where he nabbed the kid from, but to no avail.",
  ui_story_32180401_1_46_dialog_content = "Therefore, I took her to many places and showed her many pictures. But she still couldn't recall where she lived.",
  ui_story_32180401_1_47_dialog_content = "Eventually, she even took me as her mother.",
  ui_story_32180401_1_48_dialog_content = "I guess she was probably looking for emotional sustenance.",
  ui_story_32180401_1_49_dialog_content = "Are you taking me somewhere fun again, Mom?",
  ui_story_32180401_1_50_dialog_content = "Wow! This is great! I wanna go there with Daddy and Mommy!",
  ui_story_32180401_1_51_dialog_content = "Please buy me the very tall ice cream again, Mom!",
  ui_story_32180401_1_52_dialog_content = "You've been really nice to the child, Lady Sheol.",
  ui_story_32180401_1_53_dialog_content = "Alas. Every trip to look for her hometown would turn into a pleasure trip for her.",
  ui_story_32180401_1_54_dialog_content = "Now, Caelestite, you are the only one I know who can deal with this.",
  ui_story_32180401_1_55_dialog_content = "I think I know what you mean.",
  ui_story_32180401_1_56_dialog_content = "Can you recall what it was like when you were with your parents, little girl?",
  ui_story_32180401_1_57_dialog_content = "You know Lady Sheol here treats you like family, right?",
  ui_story_32180401_1_58_dialog_content = "Ahem...",
  ui_story_32180401_1_59_dialog_content = "So try to remember if you had any similar feelings before meeting Ms. Sheol.",
  ui_story_32180401_1_60_dialog_content = "Okay, I'll try it!",
  ui_story_32180401_1_61_dialog_content = "Force Boost",
  ui_story_32180401_1_62_dialog_content = "Want a pancake, Elena?",
  ui_story_32180401_1_63_dialog_content = "Let's go to the park today, Elena!",
  ui_story_32180401_1_64_dialog_content = "Time to get up, Elena. The sun's been out for a while now.",
  ui_story_32180401_1_65_dialog_content = "How is it?",
  ui_story_32180401_1_66_dialog_content = "Well, we're not completely in the dark, but just me alone...",
  ui_story_32180401_1_67_dialog_content = "Rest assured. Cloudrover will work with you one hundred percent.",
  ui_story_32180401_1_68_dialog_content = "Lady Sheol...",
  ui_story_32180401_1_69_dialog_content = "What's the matter?",
  ui_story_32180401_1_70_dialog_content = "Nothing. I'll talk to you later.",
  ui_story_32180401_1_71_dialog_content = "<color=#e8d9bb>Several days later</color>",
  ui_story_32180401_1_72_dialog_content = "Is the matter settled?",
  ui_story_32180401_1_73_dialog_content = "Yes. Speaking of which, Cloudrover's information network is very impressive!",
  ui_story_32180401_1_74_dialog_content = "The child was reluctant, but she did go back to her real parents.",
  ui_story_32180401_1_75_dialog_content = "That's good.",
  ui_story_32180401_1_76_dialog_content = "Say, why didn't you want to come along, Lady Sheol?",
  ui_story_32180401_1_77_dialog_content = "Was that necessary?",
  ui_story_32180401_1_78_dialog_content = "Don't you want to hear what Ele... that child's parents have to say to you?",
  ui_story_32180401_1_79_dialog_content = "Just some words of gratitude, I guess.",
  ui_story_32180401_1_80_dialog_content = "I'm content as long as the kid made it home safely.",
  ui_story_32180401_1_81_dialog_content = "You can be weird sometimes, like now, when you don't even want to know that child's name...",
  ui_story_32180401_1_82_dialog_content = "Now is not the time for me to find out.",
  ui_story_32180401_1_83_dialog_content = "May I ask you a question, Lady Sheol?",
  ui_story_32180401_1_84_dialog_content = "Shoot!",
  ui_story_32180401_1_85_dialog_content = "Why do charity all of a sudden?",
  ui_story_32180401_1_86_dialog_content = "Does it look like charity to you? Haven't you been doing similar things all along?",
  ui_story_32180401_1_87_dialog_content = "What? Have I?",
  ui_story_32180401_1_88_dialog_content = "This is not charity for me.",
  ui_story_32180401_1_89_dialog_content = "I just noticed the kid had a knack for numbers while she was with me.",
  ui_story_32180401_1_90_dialog_content = "With some training, she could grow into an excellent accountant for Cloudrover.",
  ui_story_32180401_1_91_dialog_content = "You seem certain the child will work for Cloudrover in the future, don't you?",
  ui_story_32180401_1_92_dialog_content = "Well, that's a trade secret.",
  ui_story_32180401_1_93_dialog_content = "But that didn't have anything to do with sending her back to her parents, right?",
  ui_story_32180401_1_94_dialog_content = "After all, keeping her around at Cloudrover Guild is what a shrewd businessperson would do, isn't it?",
  ui_story_32180401_1_95_dialog_content = "Now is not the time for that.",
  ui_story_32180401_1_96_dialog_content = "Or rather, the best place for her to be at her age is not the guild.",
  ui_story_32180401_1_97_dialog_content = "...",
  ui_story_32180401_1_98_dialog_content = "I thought you would ask the next question out of habit.",
  ui_story_32180401_1_99_dialog_content = "Guess you've matured too. Perhaps I ought to reevaluate my assessments of you.",
  ui_story_32180401_1_100_dialog_content = "You're probably wondering why I cared for that child, right?",
  ui_story_32180401_1_101_dialog_content = "Actually, I noticed the kid had a knack for numbers while she was with me.",
  ui_story_32180401_1_102_dialog_content = "With some training, she could grow into an excellent accountant for Cloudrover.",
  ui_story_32180401_1_103_dialog_content = "That didn't have anything to do with sending her back to her parents, right?",
  ui_story_32180401_1_104_dialog_content = "After all, keeping her around at Cloudrover Guild is what a shrewd businessperson would do, isn't it?",
  ui_story_32180401_1_105_dialog_content = "Now is not the time for that.",
  ui_story_32180401_1_106_dialog_content = "Or rather, the best place for her to be at her age is not the guild.",
  ui_story_32180401_1_107_dialog_content = "I knew it...",
  ui_story_32180401_1_108_dialog_content = "You do have a special place in your heart for Elena, right? Whether you were caring for her or talking about her...",
  ui_story_32180401_1_109_dialog_content = "It's not nice to peek inside a lady's mind, my dear client.",
  ui_story_32180401_1_110_dialog_content = "It's merely a feeling. No mental powers are involved.",
  ui_story_32180401_1_111_dialog_content = "Was that so obvious?",
  ui_story_32180401_1_112_dialog_content = "Guess I'll have to learn to better control my emotions.",
  ui_story_32180401_1_113_dialog_content = "Actually, there's another important reason why I did that.",
  ui_story_32180401_1_114_dialog_content = "I just... didn't want the girl to grow up without her family.",
  ui_story_32180401_1_115_dialog_content = "That's all.",
  ui_story_32180601_1_1_dialog_content = "Plop—",
  ui_story_32180601_1_2_dialog_content = "Plop—",
  ui_story_32180601_1_3_dialog_content = "Greetings, Curator!",
  ui_story_32180601_1_4_dialog_content = "Good... good, quite spirited...",
  ui_story_32180601_1_5_dialog_content = "The singer and her band are ready. Shall we start the performance now?",
  ui_story_32180601_1_6_dialog_content = "Right now? No, we should wait for the guests.",
  ui_story_32180601_1_7_dialog_content = "Sir, the troublemaker has been tied up and taken to the basement.",
  ui_story_32180601_1_8_dialog_content = "How do you want to punish him so he learns his lesson?",
  ui_story_32180601_1_9_dialog_content = "Punish... Or should we just leave him alone to cool off?",
  ui_story_32180601_1_10_dialog_content = "The leader of a small gang wants to pay his respects with a gesture of reverence. Would you like to receive him?",
  ui_story_32180601_1_11_dialog_content = "Let's pass that! Who knows what will happen after that.",
  ui_story_32180601_1_12_dialog_content = "Understood, I'll make sure they give up on their foolish fantasies.",
  ui_story_32180601_1_13_dialog_content = "We'll do our best to make you proud, sir!",
  ui_story_32180601_1_14_dialog_content = "Make you proud!",
  ui_story_32180601_1_15_dialog_content = "I hate to repeat myself, but I don't own this place.",
  ui_story_32180601_1_16_dialog_content = "Your humble character is admirable, sir. There's no doubt about it.",
  ui_story_32180601_1_17_dialog_content = "According to Ms. Sheol's document, you're the one and only curator here.",
  ui_story_32180601_1_18_dialog_content = "Please accept our sincerest respect!!!",
  ui_story_32180601_1_19_dialog_content = "How did it end up like this...",
  ui_story_32180601_1_20_dialog_content = "If I'd known, I wouldn't have responded to that invitation...",
  ui_story_32180601_1_21_dialog_content = "<color=#e8d9bb>Dear PlayerName, it's been a while since we last spoke, I hope this finds you well.</color>",
  ui_story_32180601_1_22_dialog_content = "<color=#e8d9bb>With the Cloudrover Guild expanding, I have an important matter to discuss with you.</color>",
  ui_story_32180601_1_23_dialog_content = "<color=#e8d9bb>I would be grateful if you could find the time to meet with me. I look forward to hearing from you.</color>",
  ui_story_32180601_1_24_dialog_content = "<color=#e8d9bb>With love, Sheol</color>",
  ui_story_32180601_1_25_dialog_content = "The fancy letter paper and wax seal alone screams luxury.",
  ui_story_32180601_1_26_dialog_content = "But this invitation, out of nowhere, gave me a bad feeling.",
  ui_story_32180601_1_27_dialog_content = "And Lady Sheol enjoys teasing people. Still, it says it is an important matter.",
  ui_story_32180601_1_28_dialog_content = "The joint expedition is still underway, and we can't pass up Lady Sheol's help.",
  ui_story_32180601_1_29_dialog_content = "I guess I'll have to go.",
  ui_story_32180601_1_30_dialog_content = "So this is the new club that Lady Sheol has just acquired?",
  ui_story_32180601_1_31_dialog_content = "Is this not a bit... too luxurious? What is it intended for?",
  ui_story_32180601_1_32_dialog_content = "What do you mean?",
  ui_story_32180601_1_33_dialog_content = "Oh, sorry, I'm not trying to be nosey. Lady Sheol invited me.",
  ui_story_32180601_1_34_dialog_content = "Excuse me, you're Mr. Navigator, right? This way, please!",
  ui_story_32180601_1_35_dialog_content = "Lady Sheol has been waiting for you for quite some time, but... why are you dressed like this?",
  ui_story_32180601_1_36_dialog_content = "Huh? I thought I should get dressed for such an occasion.",
  ui_story_32180601_1_37_dialog_content = "Of course. Please follow me.",
  ui_story_32180601_1_38_dialog_content = "Okay!",
  ui_story_32180601_1_39_dialog_content = "This is the place.",
  ui_story_32180601_1_40_dialog_content = "A-Are you sure?",
  ui_story_32180601_1_41_dialog_content = "That's right, Lady Sheol instructed me to escort you here upon your arrival.",
  ui_story_32180601_1_42_dialog_content = "I thought you'd come over in your bathrobe.",
  ui_story_32180601_1_43_dialog_content = "(A luxurious bathhouse... What's going on...)",
  ui_story_32180601_1_44_dialog_content = "Hmm, maybe I should just—",
  ui_story_32180601_1_45_dialog_content = "PlayerName, my dear, you're finally here.",
  ui_story_32180601_1_46_dialog_content = "Could you please not keep me waiting here any longer?",
  ui_story_32180601_1_47_dialog_content = "M-May I come in?",
  ui_story_32180601_1_48_dialog_content = "I see nothing wrong with it. We're here to discuss matters of business, are we not?",
  ui_story_32180601_1_49_dialog_content = "Come on in.",
  ui_story_32180601_1_50_dialog_content = "I... I understand now!",
  ui_story_32180601_1_51_dialog_content = "The steam is so thick... I can barely see anything.",
  ui_story_32180601_1_52_dialog_content = "What a letdown. Why are you dressed so formally? I was hoping to invite you to take a bath together.",
  ui_story_32180601_1_53_dialog_content = "What?!",
  ui_story_32180601_1_54_dialog_content = "So shy that you ran outside, how adorable, my dear.",
  ui_story_32180601_1_55_dialog_content = "Didn't I mention it in the invitation? I've been particularly looking forward to your arrival.",
  ui_story_32180601_1_56_dialog_content = "But, but who would have thought it would be in a bathhouse?",
  ui_story_32180601_1_57_dialog_content = "This is just a part of the club, my dear. Why are you so surprised? I am properly dressed. Would you like to check?",
  ui_story_32180601_1_58_dialog_content = "The bath has 19 different herbs in it, and the water's always the right temperature.",
  ui_story_32180601_1_59_dialog_content = "As my most esteemed guest, your feedback is invaluable.",
  ui_story_32180601_1_60_dialog_content = "Alright! Let's have the head maid bring you a bathrobe. Would you care to accompany me?",
  ui_story_32180601_1_61_option_content = "Why don't we... talk business first?",
  ui_story_32180601_1_62_dialog_content = "Hehe, you really are impatient...",
  ui_story_32180601_1_63_dialog_content = "But I do enjoy this thirst for business opportunities.",
  ui_story_32180601_1_64_option_content = "Please stop teasing me...",
  ui_story_32180601_1_65_dialog_content = "I believe this is still part of our business.",
  ui_story_32180601_1_66_dialog_content = "But you look so flushed. Maybe this isn't the best place for you.",
  ui_story_32180601_1_67_dialog_content = "You can go to the hall first. I'll be there in a minute to discuss the our matter at hand, the real matter.",
  ui_story_32180601_1_68_dialog_content = "You sure it's a business matter, right?",
  ui_story_32180601_1_69_dialog_content = "Of course, and it's something that will greatly benefit you. You might as well look forward to it.",
  ui_story_32180601_1_70_dialog_content = "Is there anything I can help? This is your third cup of tea.",
  ui_story_32180601_1_71_dialog_content = "I'm fine...",
  ui_story_32180601_1_72_dialog_content = "And your cheeks remain flushed.",
  ui_story_32180601_1_73_dialog_content = "Could you turn the air conditioning down for me? Thank you.",
  ui_story_32180601_1_74_dialog_content = "<color=#e8d9bb>Creeaaak...</color>",
  ui_story_32180601_1_75_dialog_content = "I apologize for the wait, my dear.",
  ui_story_32180601_1_76_dialog_content = "Here you are, how long did you spend—",
  ui_story_32180601_1_77_dialog_content = "I just want to dress up to go with your outfit.",
  ui_story_32180601_1_78_dialog_content = "It took me some time.",
  ui_story_32180601_1_79_dialog_content = "Wow, the dress...",
  ui_story_32180601_1_80_dialog_content = "You're stunning every day, but this dress...",
  ui_story_32180601_1_81_dialog_content = "Well? Is it good enough for you?",
  ui_story_32180601_1_82_dialog_content = "Stop joking around... It's not a matter of being good enough or not. I feel ashamed now.",
  ui_story_32180601_1_83_dialog_content = "Don't say that, Mr. Navigator, after all, you're the owner here.",
  ui_story_32180601_1_84_dialog_content = "I'm the... owner?",
  ui_story_32180601_1_85_dialog_content = "That's right, I invited you here today to transfer ownership of this club to your care.",
  ui_story_32180601_1_86_dialog_content = "Pfttt—I'm sorry, cough, cough... What was that?!",
  ui_story_32180601_1_87_dialog_content = "As my most valued customer, it's only right to treat you to something.",
  ui_story_32180601_1_88_dialog_content = "That's not just something!",
  ui_story_32180601_1_89_dialog_content = "If you can't explain it, I will absolutely not accept it...",
  ui_story_32180601_1_90_dialog_content = "Of course—I had my reasons.",
  ui_story_32180601_1_91_dialog_content = "This fancy club used to belong to my rival, a black market boss.",
  ui_story_32180601_1_92_dialog_content = "I took over this club to infiltrate the black market at the grand opening party.",
  ui_story_32180601_1_93_dialog_content = "If people find out that I took over this club...",
  ui_story_32180601_1_94_dialog_content = "It'll look like I'm trying to muscle in on their territory. It's too obvious, don't you think? No one's going to show up.",
  ui_story_32180601_1_95_dialog_content = "Just as I'd expect from you, very perceptive indeed.",
  ui_story_32180601_1_96_dialog_content = "What else could I do? It might become the quietest opening party in Umbraton's history...",
  ui_story_32180601_1_97_dialog_content = "... Just keep it under wraps that you bought it, isn't that okay?",
  ui_story_32180601_1_98_dialog_content = "The intelligence network in Umbraton is more sophisticated than you realize. The news of the club's acquisition by an anonymous buyer has been disseminated.",
  ui_story_32180601_1_99_dialog_content = "With so much riding on this, it's no surprise that people are starting to speculate about who bought the place.",
  ui_story_32180601_1_100_dialog_content = "The most pressing concern at this juncture is to secure a legitimate buyer to mitigate unnecessary external speculation.",
  ui_story_32180601_1_101_dialog_content = "So, who would be the most suitable buyer to send out invitations to the leaders of all the guilds in Umbraton?",
  ui_story_32180601_1_102_dialog_content = "...Me?",
  ui_story_32180601_1_103_dialog_content = "You truly understand my intentions.",
  ui_story_32180601_1_104_dialog_content = "So this is your reason for giving me the club...",
  ui_story_32180601_1_105_dialog_content = "But it is not flawless, isn't it?",
  ui_story_32180601_1_106_dialog_content = "For instance, I'm the Caelestite... Isn't it quite conspicuous?",
  ui_story_32180601_1_107_dialog_content = "And it doesn't sound right... I mean, my ancestors would cry if they knew I owned such a club.",
  ui_story_32180601_1_108_dialog_content = "So, should we still...",
  ui_story_32180601_1_109_dialog_content = "Oh dear, you're not going to say no, are you?",
  ui_story_32180601_1_110_dialog_content = "Uh, maybe we should plan things out?",
  ui_story_32180601_1_111_dialog_content = "There's no time for that. The invitations have been prepared and are awaiting your approval for distribution.",
  ui_story_32180601_1_112_dialog_content = "Of course, in your name.",
  ui_story_32180601_1_113_dialog_content = "In my name?!",
  ui_story_32180601_1_114_dialog_content = "I don't think anyone would buy into my story, the guilds or the black market boss.",
  ui_story_32180601_1_115_dialog_content = "No, no, my dear, you truly know nothing about your charm.",
  ui_story_32180601_1_116_dialog_content = "You're the sole individual capable of unifying the disparate factions of Astra.",
  ui_story_32180601_1_117_dialog_content = "Only you can bridge the gap between these distrustful leaders.",
  ui_story_32180601_1_118_dialog_content = "Not to mention, you're an important partner to the Shadowlord. This is no secret.",
  ui_story_32180601_1_119_dialog_content = "The Umbraton Guild?! Indeed... it's quite a coincidence...",
  ui_story_32180601_1_120_dialog_content = "With your positive outlook, optimism, and unmatched influence across the entire Astra...",
  ui_story_32180601_1_121_dialog_content = "When you want to establish a club in Umbraton to gather intelligence, trade goods, and host meetings for the leaders...",
  ui_story_32180601_1_122_dialog_content = "Who would dare to say no to you?",
  ui_story_32180601_1_123_dialog_content = "You've almost convinced me...",
  ui_story_32180601_1_124_dialog_content = "Don't worry. If anyone tries to mess with you, I've got your back.",
  ui_story_32180601_1_125_dialog_content = "I will do my utmost to support you and protect you, my dear.",
  ui_story_32180601_1_126_dialog_content = "Trust me, and work with me, and we'll both benefit.",
  ui_story_32180601_1_127_dialog_content = "Okay.",
  ui_story_32180601_1_128_dialog_content = "Fine, I'll just sign the agreement.",
  ui_story_32180601_1_129_dialog_content = "Great call! This is a golden opportunity for us both.",
  ui_story_32180601_1_130_dialog_content = "Right, your plan did impress me, that's for sure.",
  ui_story_32180601_1_131_dialog_content = "What's more important... I believe in you.",
  ui_story_32180601_1_132_dialog_content = "Investing in you surely it's worth something, right?",
  ui_story_32180601_1_133_dialog_content = "Humph, of course.",
  ui_story_32180601_1_134_dialog_content = "I hope you understand, we're more than just business partners.",
  ui_story_32180601_1_135_dialog_content = "I am eager to see your performance at the opening party...",
  ui_story_32180601_1_136_dialog_content = "<color=#e8d9bb>And here I am, at the opening party, anxiously waiting...</color>",
  ui_story_32180601_1_137_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_32180601_1_138_dialog_content = "Hmm? So you're the new owner of the club?",
  ui_story_32180601_1_139_dialog_content = "Isn't this just a greenhorn? Can he really be the curator here?",
  ui_story_32180601_1_140_dialog_content = "Don't tell me you're planning to open a kindergarten here?",
  ui_story_32180601_1_141_dialog_content = "Hahahahaha!",
  ui_story_32180601_1_142_dialog_content = "(I've made a few enemies in Umbraton, so I guess this was bound to happen...)",
  ui_story_32180601_1_143_dialog_content = "(However, this is the first day of business; I can't mess it up!)",
  ui_story_32180601_1_144_dialog_content = "(I have to help Lady Sheol...)",
  ui_story_32180601_1_145_dialog_content = "*coughs* You two, do you know who you're talking to?",
  ui_story_32180601_1_146_dialog_content = "Huh? How dare you speak to me like this in Umbraton. Say that again and I'll turn this place upside down.",
  ui_story_32180601_1_147_dialog_content = "If you try anything, you'll be sorry. You won't make it out of here alive.",
  ui_story_32180601_1_148_dialog_content = "What did you say!?",
  ui_story_32180601_1_149_dialog_content = "Sorry, I'm late, Mr. Navigator.",
  ui_story_32180601_1_150_dialog_content = "...?!",
  ui_story_32180601_1_151_dialog_content = "How rude of me to be late on such an important occasion!",
  ui_story_32180601_1_152_dialog_content = "Please be sure to accept the gift from the Cloudrover Guild.",
  ui_story_32180601_1_153_dialog_content = "Is that... a check from the Cloudrover Guild? And how many zeros is that?!",
  ui_story_32180601_1_154_dialog_content = "Am I supposed to pay him this much for protection?",
  ui_story_32180601_1_155_dialog_content = "My offer is a tiny fraction of what a joint expedition would cost. I hope you'll accept it anyway.",
  ui_story_32180601_1_156_dialog_content = "All I ask is that you acknowledge the Cloudrover Guild's sponsorship when discussing matters of significance with the Grand Marshal or Shadowlord.",
  ui_story_32180601_1_157_dialog_content = "It would be my greatest honor.",
  ui_story_32180601_1_158_dialog_content = "Wait, Lady Sheol, are you saying that he's connected to the joint expedition...?",
  ui_story_32180601_1_159_dialog_content = "Isn't this guy just relying on his connections with headquarters and those crazy fans? The Lovegators?",
  ui_story_32180601_1_160_dialog_content = "You two have been making quite a racket since earlier...",
  ui_story_32180601_1_161_dialog_content = "The new curator isn't fond of noise, I think it's time to ask you to leave...",
  ui_story_32180601_1_162_dialog_content = "We don't want to upset the curator and ruin the deal for everyone.",
  ui_story_32180601_1_163_dialog_content = "Please make your way back!",
  ui_story_32180601_1_164_dialog_content = "I heard that the Shadowlord wants to meet the new curator too.",
  ui_story_32180601_1_165_dialog_content = "Hey, wait a minute, how could we be here to cause trouble!",
  ui_story_32180601_1_166_dialog_content = "If the Shadowlord truly graces us with his presence... Please, let me make an investment!",
  ui_story_32180601_1_167_dialog_content = "S-Same here! If there's a chance to work with Illumina, I'm definitely interested.",
  ui_story_32180601_1_168_dialog_content = "What are you waiting for? Go grab a spot!",
  ui_story_32180601_1_169_dialog_content = "What's going on... Huh?!",
  ui_story_32180601_1_170_dialog_content = "<color=#e8d9bb>Thus, the opening party became a signing ceremony.</color>",
  ui_story_32180601_1_171_dialog_content = "<color=#e8d9bb>And the contracts signed in just half a day represent an unprecedented amount of money...</color>",
  ui_story_32180601_1_172_dialog_content = "Phew... It's killing me...",
  ui_story_32180601_1_173_dialog_content = "You've outdone yourself! I'm seeing you in a whole new light.",
  ui_story_32180601_1_174_dialog_content = "Don't be so easy in your judgment. I think there were several deals going down.",
  ui_story_32180601_1_175_dialog_content = "I was giving you signals, but all you did was puff on your pipe and urge me to sign. If anything goes wrong, don't come crying to me!",
  ui_story_32180601_1_176_dialog_content = "No worries, all you need to do is sign them. I have a lot more to consider.",
  ui_story_32180601_1_177_dialog_content = "Rest assured, I can perfectly handle most of the deals; there are just a few.",
  ui_story_32180601_1_178_dialog_content = "Perhaps it's a bit out of control.",
  ui_story_32180601_1_179_dialog_content = "So... wouldn't the gang come to me for trouble?!",
  ui_story_32180601_1_180_dialog_content = "No, no, I quit. Pick someone else for the curator!",
  ui_story_32180601_1_181_dialog_content = "Oh no, that won't do. Even you have to adhere to the spirit of the contract.",
  ui_story_32180601_1_182_dialog_content = "Besides, haven't you already experienced it just now?",
  ui_story_32180601_1_183_dialog_content = "The life of the rich? I'm fine as a Caelestite!",
  ui_story_32180601_1_184_dialog_content = "That's not what I meant, I was talking about the security services of the Cloudrover Guild.",
  ui_story_32180601_1_185_dialog_content = "Please make your way back.",
  ui_story_32180601_1_186_dialog_content = "All you need to do is make one more deal with me, and the Cloudrover Guild's security services will be free for you forever!",
  ui_story_32180601_1_187_dialog_content = "But... I refuse!",
  ui_story_32180601_1_188_dialog_content = "You're as shy as ever, aren't you, my dear...",
  ui_story_32180601_1_189_dialog_content = "However, since you've signed so many contracts today, some people might inevitably be jealous. It would be better to stay in the club and have a good rest.",
  ui_story_32180601_1_190_dialog_content = "Leaving Umbraton in the middle of the night is not safe. There's a high chance you might get kidnapped.",
  ui_story_32180601_1_191_dialog_content = "You never mentioned there was such a risk before!?",
  ui_story_32180601_1_192_dialog_content = "You'd never stay here if I told you. I'm afraid you would have already run off with your enviable Colossus.",
  ui_story_32180601_1_193_dialog_content = "So, allow me to take good care of you tonight and experience a great bath!",
  ui_story_32180601_1_194_dialog_content = "Huh? Ah? What—!!!"
}
return config
